pc/hermes-remote.ps1:
#requires -Version 5.1
<#
.SYNOPSIS
  Hermes Remote - PC-side launcher (LAN-first).

  1. Resolves the bind address: your Wi-Fi/LAN IPv4 by default
  2. Opens the Windows Firewall for that port on PRIVATE networks only
  3. Verifies the auth posture that bind actually requires
  4. Starts `hermes dashboard` bound to that address
  5. Renders the pairing QR the phone scans

.DESCRIPTION
  Design note - why LAN and not a VPN:
  the phone and the PC sit on the same home router, so the router already is
  the private network. A tailnet adds a second identity system and a second
  thing that can be "not logged in" for no reachability the LAN does not
  already give. Tailscale is still supported (-UseTailscale) for reaching the
  PC from outside the house, but it is no longer the default and never a
  requirement.

  A non-loopback bind is ALWAYS gated: `web_server.py` refuses to bind
  off-loopback unless an auth provider is registered, and it rejects `?token=`
  in that mode. So the QR carries the basic-auth credential; the session token
  only means anything on a loopback bind.

  Firewall: a fresh Windows install silently drops inbound 9119. That failure
  looks exactly like "the app can't find my PC", so the rule is created here
  rather than left as a documented manual step. It is scoped to the Private
  profile and to the local subnet - it does not expose the dashboard to a cafe
  Wi-Fi that Windows has classified as Public.

.EXAMPLE
  powershell -ExecutionPolicy Bypass -File D:\HermesMobile\pc\hermes-remote.ps1
.EXAMPLE
  # reachable from outside the house, over the tailnet instead
  powershell -ExecutionPolicy Bypass -File .\hermes-remote.ps1 -UseTailscale
#>
param(
    [switch]$Register,
    [switch]$Stop,
    [switch]$Status,
    [switch]$UseTailscale,
    [switch]$NoFirewall,
    [int]$Port = 9119,
    [string]$Username,
    [string]$Password,
    [string]$BindHost
)

$ErrorActionPreference = 'Stop'

$HermesHome   = 'D:\.hermes'
$ConfigFile   = Join-Path $HermesHome 'config.yaml'
$EnvFile      = Join-Path $HermesHome '.env'
$Python       = Join-Path $HermesHome 'hermes-agent\venv\Scripts\python.exe'
$AgentDir     = Join-Path $HermesHome 'hermes-agent'
$RenderQr     = Join-Path $PSScriptRoot 'render_qr.py'
$PasswordFile = Join-Path $PSScriptRoot '.dashboard-password'
$Tailscale    = Join-Path $env:ProgramFiles 'Tailscale\tailscale.exe'
$FwRuleName   = 'Hermes Remote dashboard'

function Write-Step($msg) { Write-Host "  $msg" -ForegroundColor Cyan }
function Write-Ok($msg)   { Write-Host "  $msg" -ForegroundColor Green }
function Write-Warn($msg) { Write-Host "  $msg" -ForegroundColor Yellow }
function Write-Bad($msg)  { Write-Host "  $msg" -ForegroundColor Red }

function Get-Sha256Hex([string]$text) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($text)
        ($sha.ComputeHash($bytes) | ForEach-Object { $_.ToString('x2') }) -join ''
    } finally {
        $sha.Dispose()
    }
}

function New-UrlSafeToken([int]$bytes = 36) {
    $buf = New-Object byte[] $bytes
    [System.Security.Cryptography.RandomNumberGenerator]::Create().GetBytes($buf)
    [Convert]::ToBase64String($buf).TrimEnd('=').Replace('+', '-').Replace('/', '_')
}

function Get-OrCreateSessionToken {
    if (Test-Path $EnvFile) {
        $line = Select-String -Path $EnvFile -Pattern '^HERMES_DASHBOARD_SESSION_TOKEN=(.+)$' -ErrorAction SilentlyContinue
        if ($line) { return $line.Matches[0].Groups[1].Value.Trim() }
    }
    $token = New-UrlSafeToken
    Add-Content -Path $EnvFile -Value ""
    Add-Content -Path $EnvFile -Value "# Stable dashboard session token - added by hermes-remote.ps1"
    Add-Content -Path $EnvFile -Value "HERMES_DASHBOARD_SESSION_TOKEN=$token"
    Write-Ok "Generated a stable dashboard session token in $EnvFile"
    return $token
}

# Pull dashboard.basic_auth.<key> out of config.yaml without a YAML parser:
# find the basic_auth block, then the first matching key inside it.
function Get-BasicAuthValue([string]$key) {
    if (-not (Test-Path $ConfigFile)) { return $null }
    $lines = Get-Content -LiteralPath $ConfigFile
    $inDashboard = $false
    $inBasic = $false
    foreach ($line in $lines) {
        if ($line -match '^dashboard:\s*$')       { $inDashboard = $true;  $inBasic = $false; continue }
        if ($line -match '^\S')                   { $inDashboard = $false; $inBasic = $false; continue }
        if (-not $inDashboard)                    { continue }
        if ($line -match '^\s{2}basic_auth:\s*$') { $inBasic = $true; continue }
        if ($line -match '^\s{2}\S')              { $inBasic = $false; continue }
        if ($inBasic -and $line -match ("^\s{4}" + [regex]::Escape($key) + ":\s*(.+?)\s*$")) {
            return $Matches[1].Trim().Trim("'").Trim('"')
        }
    }
    return $null
}

function Get-TailscaleIp {
    if (-not (Test-Path $Tailscale)) { return $null }
    $ip = & $Tailscale ip -4 2>$null | Select-Object -First 1
    if ([string]::IsNullOrWhiteSpace($ip)) { return $null }
    $ip = $ip.Trim()
    if ($ip -notmatch '^\d{1,3}(\.\d{1,3}){3}$') { return $null }
    return $ip
}

<#
  The LAN IPv4 the phone can actually route to.

  Picked by lowest interface metric among UP, non-loopback, non-virtual
  adapters holding a private address - i.e. the interface Windows itself would
  use to reach the router. Naively taking the first IPv4 lands on a Hyper-V,
  WSL, or VPN adapter (172.x / 192.168.56.x), and a QR carrying an address that
  only exists inside the PC is a pairing that fails with no visible cause.
#>
function Get-LanIp {
    $candidates = Get-NetIPAddress -AddressFamily IPv4 -ErrorAction SilentlyContinue |
        Where-Object {
            $_.IPAddress -notmatch '^(127\.|169\.254\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.)' -and
            $_.PrefixOrigin -ne 'WellKnown' -and
            ($_.IPAddress -match '^192\.168\.' -or $_.IPAddress -match '^10\.' -or
             $_.IPAddress -match '^172\.(1[6-9]|2\d|3[01])\.')
        }
    if (-not $candidates) { return $null }

    $best = $null
    $bestMetric = [int]::MaxValue
    foreach ($addr in $candidates) {
        $iface = Get-NetIPInterface -InterfaceIndex $addr.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue
        if (-not $iface -or $iface.ConnectionState -ne 'Connected') { continue }
        $adapter = Get-NetAdapter -InterfaceIndex $addr.InterfaceIndex -ErrorAction SilentlyContinue
        if (-not $adapter -or $adapter.Status -ne 'Up') { continue }
        # Virtual switches and loopback-ish adapters are never the route to the phone.
        if ($adapter.InterfaceDescription -match 'Hyper-V|Virtual|VMware|VirtualBox|Loopback|TAP-|Tailscale|WireGuard') { continue }
        $metric = [int]$iface.InterfaceMetric
        if ($metric -lt $bestMetric) { $bestMetric = $metric; $best = $addr.IPAddress }
    }
    return $best
}

function Test-Admin {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    (New-Object Security.Principal.WindowsPrincipal($id)).IsInRole(
        [Security.Principal.WindowsBuiltInRole]::Administrator)
}

<#
  Allow inbound TCP $Port from the local subnet on Private/Domain profiles.

  RemoteAddress=LocalSubnet plus Profile=Private,Domain is the narrowest rule
  that still lets the phone in: it does not apply at all on a network Windows
  has classified Public, so taking the laptop to a cafe does not carry the
  opening along with it.
#>
function Set-FirewallRule([int]$port) {
    $existing = Get-NetFirewallRule -DisplayName $FwRuleName -ErrorAction SilentlyContinue
    if ($existing) {
        $filter = $existing | Get-NetFirewallPortFilter
        if ($filter.LocalPort -eq "$port") {
            Write-Ok "Firewall: '$FwRuleName' already allows TCP $port on private networks"
            return $true
        }
        if (-not (Test-Admin)) { return $false }
        Remove-NetFirewallRule -DisplayName $FwRuleName -ErrorAction SilentlyContinue
    }
    if (-not (Test-Admin)) { return $false }
    New-NetFirewallRule -DisplayName $FwRuleName `
        -Description 'Lets the Hermes Remote phone app reach the dashboard on this LAN.' `
        -Direction Inbound -Action Allow -Protocol TCP -LocalPort $port `
        -Profile Private,Domain -RemoteAddress LocalSubnet -Enabled True | Out-Null
    Write-Ok "Firewall: allowed inbound TCP $port from the local subnet (private networks only)"
    return $true
}

# The network the PC is on must be Private, or the rule above never applies.
function Test-PrivateProfile {
    $profiles = Get-NetConnectionProfile -ErrorAction SilentlyContinue |
        Where-Object { $_.IPv4Connectivity -ne 'Disconnected' }
    if (-not $profiles) { return $true }
    $public = $profiles | Where-Object { $_.NetworkCategory -eq 'Public' }
    if ($public) {
        Write-Warn "Network '$($public[0].Name)' is set to Public - Windows blocks incoming"
        Write-Warn "connections there. Settings > Network > Properties > Private network."
        return $false
    }
    return $true
}

# ---------------------------------------------------------------- subcommands

if ($Stop) {
    Push-Location $AgentDir
    try { & $Python -m hermes_cli.main dashboard --stop } finally { Pop-Location }
    exit 0
}

if ($Status) {
    Push-Location $AgentDir
    try { & $Python -m hermes_cli.main dashboard --status } finally { Pop-Location }
    exit 0
}

# --------------------------------------------------------------------- bind

Write-Host ""
Write-Host "Hermes Remote - starting dashboard" -ForegroundColor White
Write-Host ""

if ($BindHost) {
    $bind = $BindHost
    Write-Step "Bind: $bind (explicit)"
} elseif ($UseTailscale) {
    $bind = Get-TailscaleIp
    if ($bind) { Write-Step "Bind: $bind (tailnet)" }
    else { Write-Bad "Tailscale is not installed or not logged in." }
} else {
    $bind = Get-LanIp
    if ($bind) { Write-Step "Bind: $bind (this PC on your Wi-Fi/LAN)" }
}

if (-not $bind) {
    $bind = '127.0.0.1'
    Write-Bad "No LAN address found - is this PC connected to Wi-Fi or Ethernet?"
    Write-Bad "Binding LOOPBACK; your phone cannot reach this."
    Write-Host ""
}

if ($bind -eq '0.0.0.0') { throw 'Refusing to bind 0.0.0.0 - unsandboxed execution must not face every network.' }

$isLoopback = ($bind -eq '127.0.0.1' -or $bind -eq 'localhost' -or $bind -eq '::1')

# ------------------------------------------------------------------ firewall

if (-not $isLoopback -and -not $NoFirewall) {
    Test-PrivateProfile | Out-Null
    if (-not (Set-FirewallRule $Port)) {
        Write-Warn "Firewall rule needs admin rights and was not created."
        Write-Warn "If the phone cannot see this PC, run once in an elevated PowerShell:"
        Write-Host "    New-NetFirewallRule -DisplayName '$FwRuleName' -Direction Inbound ``" -ForegroundColor DarkGray
        Write-Host "      -Action Allow -Protocol TCP -LocalPort $Port -Profile Private,Domain ``" -ForegroundColor DarkGray
        Write-Host "      -RemoteAddress LocalSubnet" -ForegroundColor DarkGray
        Write-Host ""
    }
}

# ---------------------------------------------------- auth posture preflight

$cfgUser = Get-BasicAuthValue 'username'
$cfgHash = Get-BasicAuthValue 'password_hash'
$cfgPass = Get-BasicAuthValue 'password'

if (-not $Username) { $Username = $cfgUser }
if (-not $Password) {
    if (Test-Path $PasswordFile) { $Password = (Get-Content -LiteralPath $PasswordFile -Raw).Trim() }
    elseif ($cfgPass)            { $Password = $cfgPass }
}

if (-not $isLoopback) {
    # The dashboard REFUSES to start on a public bind with no auth provider.
    # Catch that here with a readable message instead of a SystemExit traceback.
    if (-not $Username -or -not ($cfgHash -or $cfgPass)) {
        Write-Bad "Binding $bind engages the auth gate, but dashboard.basic_auth is not configured."
        Write-Host ""
        Write-Host "  Fix it with:" -ForegroundColor Yellow
        Write-Host "    hermes config set dashboard.basic_auth.username <name>"
        Write-Host "    # then hash a password and set dashboard.basic_auth.password_hash"
        Write-Host ""
        exit 1
    }
    if (-not $Password) {
        $secure = Read-Host "Dashboard password for '$Username'" -AsSecureString
        $Password = [Runtime.InteropServices.Marshal]::PtrToStringAuto(
            [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure))
    }
    Write-Ok "Auth: gated (basic) as '$Username'"
} else {
    Write-Step "Auth: loopback (session token)"
}

$token = Get-OrCreateSessionToken
$env:HERMES_DASHBOARD_SESSION_TOKEN = $token

# -------------------------------------------------------------------- launch

# Already up on this address? Reuse it rather than starting a second server
# that will die on a port conflict and look like a failure.
$status = $null
try { $status = Invoke-RestMethod -Uri "http://${bind}:$Port/api/status" -TimeoutSec 2 } catch { }

if ($status) {
    Write-Ok "Dashboard already running on http://${bind}:$Port"
} else {
    Write-Step "Starting dashboard on http://${bind}:$Port ..."

    $stdout = Join-Path $env:TEMP 'hermes-dashboard.out.log'
    $stderr = Join-Path $env:TEMP 'hermes-dashboard.err.log'

    $proc = Start-Process -FilePath $Python -PassThru -WindowStyle Hidden `
        -ArgumentList @('-m', 'hermes_cli.main', 'dashboard',
                        '--host', $bind, '--port', "$Port", '--no-open', '--skip-build') `
        -WorkingDirectory $AgentDir `
        -RedirectStandardOutput $stdout -RedirectStandardError $stderr

    for ($i = 0; $i -lt 30; $i++) {
        Start-Sleep -Milliseconds 700
        if ($proc.HasExited) { break }
        try {
            $status = Invoke-RestMethod -Uri "http://${bind}:$Port/api/status" -TimeoutSec 3
            break
        } catch { }
    }

    if ($proc.HasExited -or -not $status) {
        Write-Bad "Dashboard did not come up."
        if (Test-Path $stderr) {
            $tail = Get-Content -LiteralPath $stderr -Tail 25 -ErrorAction SilentlyContinue
            if ($tail) { Write-Host ""; $tail | ForEach-Object { Write-Host "  $_" -ForegroundColor DarkGray } }
        }
        exit 1
    }
}

Write-Ok ("Dashboard up: Hermes v{0}, gateway={1}, auth_required={2}" -f `
    $status.version, $status.gateway_state, $status.auth_required)

# The bind and the auth mode must agree, or the phone will fail at connect
# time with a confusing error instead of here with a clear one.
if ($status.auth_required -and -not $Password) {
    Write-Bad "Server reports auth_required=true but no password is available for the QR."
    exit 1
}

# ----------------------------------------------------------------------- QR

if ($status.auth_required) {
    $payload = [ordered]@{
        v = 1; name = $env:COMPUTERNAME; host = $bind; port = $Port
        auth = 'gated'; provider = 'basic'
        username = $Username; password = $Password
        fingerprint = (Get-Sha256Hex "$Username`:$Password")
    }
} else {
    $payload = [ordered]@{
        v = 1; name = $env:COMPUTERNAME; host = $bind; port = $Port
        auth = 'token'; token = $token
        fingerprint = (Get-Sha256Hex $token)
    }
}

$json = ($payload | ConvertTo-Json -Compress)

Write-Host ""
# Piped on stdin - render_qr.py already supports it, and this keeps a payload
# full of braces and quotes out of PowerShell's native-argument handling.
$json | & $Python $RenderQr
Write-Host ""
Write-Ok "Scan the QR with Hermes Remote (phone on the same Wi-Fi)."
Write-Host "  Address:  http://${bind}:$Port"
Write-Host "  Stop later with: powershell -File `"$PSCommandPath`" -Stop"
Write-Host ""

if ($Register) {
    $action = New-ScheduledTaskAction -Execute 'powershell.exe' `
        -Argument "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    $trigger = New-ScheduledTaskTrigger -AtLogOn -User $env:USERNAME
    Register-ScheduledTask -TaskName 'Hermes Remote Dashboard' -Action $action -Trigger $trigger `
        -Description 'Starts the Hermes dashboard on the LAN address and prints the pairing QR.' -Force | Out-Null
    Write-Ok 'Scheduled task "Hermes Remote Dashboard" registered (runs at logon).'
}

app/src/main/java/com/hermes/mobile/core:
package com.hermes.mobile.core.connection

import com.hermes.mobile.core.transport.RestClient
import com.hermes.mobile.core.transport.RestException
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.booleanOrNull
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.put

/** A credential problem the user can act on. Never swallow these. */
class AuthException(message: String, cause: Throwable? = null) : Exception(message, cause)

/**
 * How the app proves itself to the dashboard.
 *
 * TOKEN — loopback / trusted bind: `?token=<session token>` on the WS. REST on
 *         loopback needs no credential at all (Phase 0 §0.5).
 *
 * GATED — every non-loopback bind. The `insecure` mode the spec assumed was
 *         removed in June 2026: `web_server.py` refuses to bind off-loopback
 *         without an auth provider and rejects `?token=` outright. The client
 *         must instead
 *           1. POST /auth/password-login   → sets hermes_session_* cookies
 *           2. POST /api/auth/ws-ticket    → {"ticket", "ttl_seconds": 30}
 *           3. open the WS with ?ticket=<ticket>
 *         Tickets are SINGLE USE with a 30 s TTL, so one is minted per socket
 *         and per reconnect — never cached.
 *
 * [wsUrl] is `suspend` for exactly that reason. The previous version had a
 * synchronous `wsUrl` that threw `UnsupportedOperationException` in gated mode,
 * which is what surfaced as "connect ends in auth failure".
 */
sealed interface CredentialStrategy {

    /** Perform any one-time login. Idempotent; safe to call before every connect. */
    suspend fun ensureAuthenticated() {}

    /** Absolute ws:// URL carrying a valid credential. Mints a fresh ticket in gated mode. */
    suspend fun wsUrl(base: String, path: String): String

    /** Value for a REST `Authorization` header, or null when cookies carry the session. */
    fun restAuthorization(): String? = null

    // -----------------------------------------------------------------------

    data class Token(val token: String) : CredentialStrategy {
        override suspend fun wsUrl(base: String, path: String): String =
            "$base$path?token=$token"

        override fun restAuthorization(): String = "Bearer $token"
    }

    // -----------------------------------------------------------------------

    class Gated(
        private val httpBase: String,
        private val username: String,
        private val password: String,
        private val rest: RestClient,
        private val cookies: HermesCookieJar,
        private val host: String,
        private val provider: String = DEFAULT_PROVIDER,
    ) : CredentialStrategy {

        private val loginLock = Mutex()

        override suspend fun ensureAuthenticated() {
            if (cookies.hasSessionFor(host)) return
            loginLock.withLock {
                if (cookies.hasSessionFor(host)) return
                login()
            }
        }

        override suspend fun wsUrl(base: String, path: String): String {
            ensureAuthenticated()
            return "$base$path?ticket=${mintTicket()}"
        }

        /**
         * POST /auth/password-login.
         *
         * The route binds a Pydantic model, so this must be a JSON body — a
         * form-encoded post gets 422.
         */
        private suspend fun login() {
            val body: JsonObject = buildJsonObject {
                put("provider", provider)
                put("username", username)
                put("password", password)
                put("next", "/")
            }
            val result = try {
                rest.postJson(httpBase, PATH_LOGIN, body)
            } catch (e: RestException) {
                throw AuthException(loginFailureMessage(e), e)
            }
            val ok = result.jsonObject["ok"]?.jsonPrimitive?.booleanOrNull ?: false
            if (!ok) throw AuthException("Dashboard rejected the login.")
            if (!cookies.hasSessionFor(host)) {
                throw AuthException(
                    "Login succeeded but no session cookie was stored. " +
                        "Check that the HTTP client has a cookie jar installed.",
                )
            }
        }

        /**
         * Mint a single-use 30 s ticket. On 401 the cookie has expired
         * (12 h default TTL) — clear it, log in once more, and retry exactly
         * once so a stale session self-heals instead of surfacing as a
         * connection failure.
         */
        private suspend fun mintTicket(retrying: Boolean = false): String {
            val result = try {
                rest.postJson(httpBase, PATH_WS_TICKET, buildJsonObject { })
            } catch (e: RestException) {
                if (e.code == 401 && !retrying) {
                    cookies.clear()
                    loginLock.withLock { login() }
                    return mintTicket(retrying = true)
                }
                throw AuthException(ticketFailureMessage(e), e)
            }
            val ticket = result.jsonObject["ticket"]?.jsonPrimitive?.contentOrNull
            if (ticket.isNullOrBlank()) {
                throw AuthException("Dashboard returned no ws-ticket.")
            }
            return ticket
        }

        private fun loginFailureMessage(e: RestException): String = when (e.code) {
            401 -> "Wrong username or password for the dashboard."
            404 -> "This dashboard has no '$provider' password provider configured."
            429 -> "Too many login attempts — wait a minute and try again."
            503 -> "The dashboard's auth provider is unreachable."
            else -> "Login failed (HTTP ${e.code})."
        }

        private fun ticketFailureMessage(e: RestException): String = when (e.code) {
            401 -> "Session expired and could not be renewed."
            else -> "Could not mint a WebSocket ticket (HTTP ${e.code})."
        }

        private companion object {
            const val PATH_LOGIN = "/auth/password-login"
            const val PATH_WS_TICKET = "/api/auth/ws-ticket"
        }
    }

    companion object {
        /** Bundled username/password provider — plugins/dashboard_auth/basic. */
        const val DEFAULT_PROVIDER = "basic"
    }
}

package com.hermes.mobile.core.transport

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody

/**
 * Subset of `GET /api/status` we actually render.
 *
 * The wire is snake_case. Without these [SerialName]s every field below stayed
 * at its default — which is why `authRequired` read as `false` on a gated
 * server and the client kept choosing token auth against a dashboard that
 * rejects tokens. `ignoreUnknownKeys` in [HermesJson] hid the mismatch.
 *
 * Every field is either optional or lenient ON PURPOSE. `gateway_platforms`
 * was declared `List<String>` while the server sends
 * `{"telegram": {"state": ...}}`; that mismatch threw a JsonDecodingException
 * out of EVERY `/api/status` parse, which the connect path reports as
 * "Can't reach your PC" — a wrong type on a field nobody renders made the app
 * unusable. Status is a diagnostic document owned by the server: decode it
 * permissively, and never let an unread field fail the parse.
 */
@Serializable
data class ServerStatus(
    val version: String? = null,
    @SerialName("release_date") val releaseDate: String? = null,
    @SerialName("gateway_running") val gatewayRunning: Boolean = false,
    @SerialName("gateway_state") val gatewayState: String? = null,
    @SerialName("gateway_platforms") val gatewayPlatforms: JsonElement? = null,
    @SerialName("active_sessions") val activeSessions: Int = 0,
    @SerialName("active_agents") val activeAgents: Int = 0,
    @SerialName("auth_required") val authRequired: Boolean = false,
    @SerialName("auth_providers") val authProviders: List<String> = emptyList(),
    @SerialName("auth_flows") val authFlows: List<String> = emptyList(),
    @SerialName("gateway_mode") val gatewayMode: String? = null,
    @SerialName("can_update_hermes") val canUpdate: Boolean = false,
    val overall: String? = null,
    @SerialName("hermes_home") val hermesHome: String? = null,
) {
    /** Platform names, whether the server sent an object or a list. */
    val platformNames: List<String>
        get() = when (val p = gatewayPlatforms) {
            is JsonObject -> p.keys.toList()
            is JsonArray -> p.mapNotNull { (it as? JsonPrimitive)?.contentOrNull }
            else -> emptyList()
        }
}

class RestException(val code: Int, message: String) : Exception("HTTP $code: $message")

/** Percent-encode one query-string value. */
fun q(value: String): String = java.net.URLEncoder.encode(value, "UTF-8")

/**
 * REST half of the control plane (`/api/…`).
 *
 * Loopback needs no credential. A gated deployment authenticates with the
 * `hermes_session_*` cookies the OkHttp client's jar holds — see
 * [com.hermes.mobile.core.connection.HermesCookieJar]. This class never
 * touches credentials itself.
 */
class RestClient(
    private val httpClient: OkHttpClient,
) {
    suspend fun getStatus(baseUrl: String): ServerStatus =
        getJson(baseUrl, "/api/status").let {
            HermesJson.decodeFromJsonElement(ServerStatus.serializer(), it)
        }

    suspend fun getJson(baseUrl: String, path: String): JsonElement =
        execute(Request.Builder().url(baseUrl + path).get())

    suspend fun postJson(baseUrl: String, path: String, payload: JsonObject): JsonElement =
        execute(Request.Builder().url(baseUrl + path).post(payload.body()))

    suspend fun putJson(baseUrl: String, path: String, payload: JsonObject): JsonElement =
        execute(Request.Builder().url(baseUrl + path).put(payload.body()))

    suspend fun deleteJson(baseUrl: String, path: String): JsonElement =
        execute(Request.Builder().url(baseUrl + path).delete())

    /** Raw bytes — file downloads, where a JSON parse would be wrong. */
    suspend fun getBytes(baseUrl: String, path: String): ByteArray =
        withContext(Dispatchers.IO) {
            val req = Request.Builder().url(baseUrl + path).get().build()
            httpClient.newCall(req).execute().use { resp ->
                if (!resp.isSuccessful) {
                    throw RestException(resp.code, resp.body?.string()?.take(300).orEmpty())
                }
                resp.body?.bytes() ?: ByteArray(0)
            }
        }

    private suspend fun execute(builder: Request.Builder): JsonElement =
        withContext(Dispatchers.IO) {
            httpClient.newCall(builder.build()).execute().use { resp ->
                val body = resp.body?.string().orEmpty()
                if (!resp.isSuccessful) throw RestException(resp.code, body.take(300))
                HermesJson.parseToJsonElement(body.ifBlank { "null" })
            }
        }

    /** Reachability probe used by profile racing — fast timeout, no retries. */
    suspend fun probe(baseUrl: String, timeoutMs: Long = 1500): Boolean =
        withContext(Dispatchers.IO) {
            runCatching {
                val client = httpClient.newBuilder()
                    .connectTimeout(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS)
                    .readTimeout(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS)
                    .build()
                client.newCall(Request.Builder().url("$baseUrl/api/status").get().build())
                    .execute().use { it.isSuccessful }
            }.getOrDefault(false)
        }

    private companion object {
        val JSON_MEDIA = "application/json; charset=utf-8".toMediaType()
        fun JsonObject.body() = toString().toRequestBody(JSON_MEDIA)
    }
}

package com.hermes.mobile.core.connection

import com.hermes.mobile.core.net.DiscoveredPc
import com.hermes.mobile.core.net.LanDiscovery
import com.hermes.mobile.core.net.NetworkMonitor
import com.hermes.mobile.core.net.PrivateHosts
import com.hermes.mobile.core.transport.ChannelState
import com.hermes.mobile.core.transport.HermesClient
import com.hermes.mobile.core.transport.HermesEvent
import com.hermes.mobile.core.transport.ReconnectPolicy
import com.hermes.mobile.core.transport.ServerStatus
import com.hermes.mobile.core.vault.SecureVault
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.async
import kotlinx.coroutines.awaitAll
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import javax.inject.Inject
import javax.inject.Singleton

/** What the UI banner renders. */
sealed interface ConnState {
    data object NoProfile : ConnState
    data object Probing : ConnState
    data class Connecting(val profile: ConnectionProfile) : ConnState
    data class Connected(val profile: ConnectionProfile, val status: ServerStatus?) : ConnState
    data class Reconnecting(val profile: ConnectionProfile, val attempt: Int) : ConnState
    data class Failed(val profile: ConnectionProfile?, val message: String) : ConnState
}

/**
 * Owns the active [HermesClient], profile selection, reachability racing and
 * the reconnect loop.
 *
 * Auth mode is DISCOVERED, not configured: `GET /api/status` is a public path,
 * so we read `auth_required` off it before choosing a [CredentialStrategy].
 *
 * Three robustness properties this class is responsible for, all of which were
 * missing and all of which show up as "the app just says reconnecting":
 *
 *  1. **DHCP drift self-heal.** The PC's LAN address is a lease and it moves.
 *     When the saved address stops answering, the /24 is swept and the profile
 *     is re-bound to the Hermes that answers — automatically when exactly one
 *     does, and surfaced as a choice when several do.
 *  2. **Link-aware retry.** A Wi-Fi drop used to leave the socket in timed
 *     backoff; now a link transition wakes the loop immediately and resets it.
 *  3. **Liveness.** A phone that sleeps through a TCP half-open sees a socket
 *     that is "connected" and silent. A heartbeat `ping` proves otherwise.
 */
@Singleton
class ConnectionManager @Inject constructor(
    private val vault: SecureVault,
    private val clientFactory: HermesClientFactory,
    private val networkMonitor: NetworkMonitor,
    private val lanDiscovery: LanDiscovery,
) {
    private val managerScope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    private val _state = MutableStateFlow<ConnState>(ConnState.NoProfile)
    val state: StateFlow<ConnState> = _state.asStateFlow()

    var client: HermesClient? = null
        private set

    private val _clientFlow = MutableStateFlow<HermesClient?>(null)
    val clientFlow: StateFlow<HermesClient?> = _clientFlow.asStateFlow()

    private val _channelState = MutableStateFlow<ChannelState>(ChannelState.Disconnected)
    val channelState: StateFlow<ChannelState> = _channelState.asStateFlow()

    private val _globalEvents = MutableSharedFlow<HermesEvent>(extraBufferCapacity = 256)
    val globalEvents: SharedFlow<HermesEvent> = _globalEvents.asSharedFlow()

    /** Non-fatal notices worth showing once (rebinds, ambiguous discovery). */
    private val _notices = MutableSharedFlow<String>(extraBufferCapacity = 8)
    val notices: SharedFlow<String> = _notices.asSharedFlow()

    /** Result of the last LAN sweep, for the pairing screen's picker. */
    private val _discovered = MutableStateFlow<List<DiscoveredPc>>(emptyList())
    val discovered: StateFlow<List<DiscoveredPc>> = _discovered.asStateFlow()

    private val _scanning = MutableStateFlow(false)
    val scanning: StateFlow<Boolean> = _scanning.asStateFlow()

    /** Every paired PC, for the profile switcher. Secrets stay in the vault. */
    val profiles: StateFlow<List<ConnectionProfile>> = vault.profiles

    /** The profile currently bound, or null when disconnected. */
    val currentProfile: ConnectionProfile? get() = activeProfile

    private var activeProfile: ConnectionProfile? = null
    private var activeConnection: HermesConnection? = null
    private var activeStrategy: CredentialStrategy? = null
    private var watchJob: Job? = null
    private var reconnectJob: Job? = null
    private var heartbeatJob: Job? = null
    private val backoff = ReconnectPolicy()

    /** Serialises connect attempts so a manual retry cannot race the loop. */
    private val connectLock = Mutex()

    /** Set while a reconnect loop is driving; keeps connectTo from killing it. */
    @Volatile
    private var reconnecting = false

    init {
        networkMonitor.start()
        managerScope.launch {
            networkMonitor.changes.collect { onLinkChanged() }
        }
    }

    // ------------------------------------------------------------------ pair

    /** Entry point from the UI layer: pair → save → connect. */
    suspend fun pairAndConnect(payload: QrPairingPayload) {
        if (!payload.isUsable()) {
            _state.value = ConnState.Failed(null, "That pairing code is missing its credential")
            return
        }
        val profile = payload.toProfile()
        PrivateHosts.rejectionReason(profile.host, profile.secure)?.let {
            _state.value = ConnState.Failed(null, it)
            return
        }
        vault.saveProfile(profile, payload.vaultSecret())
        connectTo(profile)
    }

    /**
     * Manual entry (same as QR, minus the camera). [secret] is either a bare
     * dashboard session token (loopback) or `user:password` (gated) — the
     * server tells us which applies, so the user does not have to.
     */
    suspend fun addManualProfile(
        label: String,
        host: String,
        port: Int,
        secret: String,
        secure: Boolean = false,
    ) {
        PrivateHosts.rejectionReason(host, secure)?.let {
            _state.value = ConnState.Failed(null, it)
            return
        }
        val profile = ConnectionProfile(
            id = profileIdFor(host, port),
            label = label.ifBlank { host },
            host = host,
            port = port,
            auth = if (splitBasicSecret(secret) != null) AuthKind.GATED else AuthKind.TOKEN,
            secure = secure,
            isDefault = true,
        )
        vault.saveProfile(profile, secret)
        connectTo(profile)
    }

    // -------------------------------------------------------------- discovery

    /**
     * Sweep the Wi-Fi for dashboards and publish the result. Used by the
     * pairing screen's "Find my PC" and by the self-heal path.
     */
    suspend fun scanLan(port: Int = 9119): List<DiscoveredPc> {
        _scanning.value = true
        return try {
            lanDiscovery.sweep(port).also { _discovered.value = it }
        } finally {
            _scanning.value = false
        }
    }

    /**
     * Attach to a PC found by the sweep, reusing a stored credential when this
     * host was paired before. Returns false when a credential is still needed.
     */
    suspend fun connectToDiscovered(pc: DiscoveredPc): Boolean {
        val id = profileIdFor(pc.host, pc.port)
        val existing = vault.profiles.value.firstOrNull { it.id == id }
        if (existing != null && vault.secretFor(id) != null) {
            connectTo(existing)
            return true
        }
        // A profile paired to a different address, whose credential still applies.
        val reusable = vault.profiles.value.firstOrNull { vault.secretFor(it.id) != null }
        if (reusable != null) {
            rebindProfile(reusable, pc.host, pc.port)
            return true
        }
        return false
    }

    /**
     * Move an existing profile (and its secret) to a new address, then connect.
     * The profile id is derived from host:port, so the secret is re-keyed here
     * — dropping that step is how a rebind silently loses the credential.
     */
    private suspend fun rebindProfile(profile: ConnectionProfile, host: String, port: Int) {
        val secret = vault.secretFor(profile.id) ?: run {
            _state.value = ConnState.Failed(profile, "credential missing for ${profile.label}")
            return
        }
        val moved = profile.copy(id = profileIdFor(host, port), host = host, port = port)
        vault.saveProfile(moved, secret)
        if (moved.id != profile.id) vault.removeProfile(profile.id)
        _notices.tryEmit("${moved.label} moved to $host — reconnected")
        connectTo(moved)
    }

    /**
     * The saved address is dead. Sweep, and re-bind when the answer is
     * unambiguous. Returns true when a rebind happened.
     */
    private suspend fun rediscoverAndRebind(profile: ConnectionProfile): Boolean {
        if (!networkMonitor.onLocalNetwork) return false
        val found = scanLan(profile.port)
        return when {
            found.isEmpty() -> false
            found.size == 1 -> {
                rebindProfile(profile, found.first().host, found.first().port)
                true
            }
            else -> {
                _notices.tryEmit(
                    "Found ${found.size} Hermes PCs on this Wi-Fi — pick one in Connect.",
                )
                false
            }
        }
    }

    // --------------------------------------------------------------- connect

    suspend fun autoConnect() {
        val profiles = vault.profiles.value
        if (profiles.isEmpty()) {
            _state.value = ConnState.NoProfile
            return
        }
        _state.value = ConnState.Probing
        val winner = raceProfiles(profiles)
        if (winner != null) {
            connectTo(winner)
            return
        }
        // Nothing at the saved addresses — the lease probably moved.
        val healed = rediscoverAndRebind(profiles.first())
        if (!healed) {
            _state.value = ConnState.Failed(
                profiles.firstOrNull(),
                if (networkMonitor.onLocalNetwork) {
                    "No Hermes found on this Wi-Fi. Is the dashboard running on your PC?"
                } else {
                    "Not on Wi-Fi. Hermes Remote reaches your PC over your home network."
                },
            )
        }
    }

    /** First profile whose /api/status answers within the probe timeout wins. */
    suspend fun raceProfiles(profiles: List<ConnectionProfile>): ConnectionProfile? =
        coroutineScope {
            profiles
                .map { profile -> async { profile to probeProfile(profile) } }
                .awaitAll()
                .firstOrNull { it.second }
                ?.first
        }

    private suspend fun probeProfile(profile: ConnectionProfile): Boolean =
        clientFactory.newProbeClient(managerScope).rest.probe(profile.httpBase)

    suspend fun connectTo(profile: ConnectionProfile) = connectLock.withLock {
        connectLocked(profile)
    }

    /**
     * Record a connect failure AND make sure something will try again.
     *
     * This is the hole that survived on-device testing: a Wi-Fi off/on cycle
     * fires a link event, the immediate connect attempt loses the race with
     * DHCP, `connectTo` sets Failed — and then nothing ever retried, because
     * the retry loop only ran off ChannelState.Degraded and the socket had
     * never opened. The app sat on "Couldn't connect" next to a discovery card
     * listing the very PC it could not reach. Every failure path now re-arms
     * the loop, so "stuck" is not reachable while a profile is bound.
     */
    private fun failAndRetry(profile: ConnectionProfile?, message: String) {
        _state.value = ConnState.Failed(profile, message)
        if (profile != null) reconnectLoop(profile)
    }

    private suspend fun connectLocked(profile: ConnectionProfile) {
        val secret = vault.secretFor(profile.id)
        if (secret == null) {
            // A missing credential is NOT retryable — re-pairing is the fix.
            _state.value = ConnState.Failed(profile, "credential missing for ${profile.label}")
            return
        }
        // Only a caller from OUTSIDE the reconnect loop may cancel it. The old
        // code cancelled unconditionally, so the loop's own connectTo killed
        // the coroutine it was running in, mid-connect.
        if (!reconnecting) reconnectJob?.cancel()
        teardown()
        _state.value = ConnState.Connecting(profile)

        val connection = clientFactory.newConnection(managerScope)
        val newClient = connection.client
        activeConnection = connection
        client = newClient
        _clientFlow.value = newClient
        activeProfile = profile

        // /api/status is public on every bind, so this works before we hold any
        // credential — and it is what tells us WHICH credential to present.
        val status = runCatching { newClient.rest.getStatus(profile.httpBase) }.getOrNull()
        if (status == null) {
            failAndRetry(
                profile,
                "Can't reach ${profile.host}:${profile.port}. Is the dashboard running?",
            )
            return
        }

        val strategy = buildStrategy(profile, secret, status, connection)
        if (strategy == null) return // state already set to Failed with a reason
        activeStrategy = strategy

        val url = try {
            strategy.wsUrl(profile.wsBase, "/api/ws")
        } catch (e: AuthException) {
            // Wrong password is terminal; a transport blip during the ticket
            // mint is not. Only the latter should keep retrying.
            _state.value = ConnState.Failed(profile, e.message ?: "Authentication failed")
            return
        } catch (e: Exception) {
            failAndRetry(
                profile,
                "Authentication failed: ${e.message ?: e.javaClass.simpleName}",
            )
            return
        }

        newClient.rpc.onReady = {
            backoff.reset()
            reconnecting = false
            vault.markSeen(profile.id)
            _state.value = ConnState.Connected(profile, status)
        }
        newClient.rpc.connect(url)
        startWatching(profile, newClient)
        startHeartbeat(newClient)
    }

    /**
     * Pick the credential the server will actually accept.
     *
     * `auth_required == true` ⇒ every non-public path (and the WS upgrade)
     * needs a cookie session + a single-use ticket; `?token=` is refused.
     */
    private fun buildStrategy(
        profile: ConnectionProfile,
        secret: String,
        status: ServerStatus,
        connection: HermesConnection,
    ): CredentialStrategy? {
        if (!status.authRequired) {
            return CredentialStrategy.Token(secret)
        }
        val creds = splitBasicSecret(secret)
        if (creds == null) {
            _state.value = ConnState.Failed(
                profile,
                "${profile.label} requires a dashboard login. Re-pair with the QR, " +
                    "or enter the credential as user:password.",
            )
            return null
        }
        val (username, password) = creds
        return CredentialStrategy.Gated(
            httpBase = profile.httpBase,
            username = username,
            password = password,
            rest = connection.client.rest,
            cookies = connection.cookies,
            host = profile.host,
        )
    }

    /**
     * A credentialled ws:// URL for an ancillary socket (`/api/pty`,
     * `/api/events`). Mints a FRESH ticket in gated mode — tickets are single
     * use, so every socket needs its own.
     */
    suspend fun authorizedWsUrl(path: String): String? {
        val profile = activeProfile ?: return null
        val strategy = activeStrategy ?: return null
        return strategy.wsUrl(profile.wsBase, path)
    }

    // --------------------------------------------------------------- watching

    private fun startWatching(profile: ConnectionProfile, watched: HermesClient) {
        watchJob?.cancel()
        watchJob = managerScope.launch {
            launch {
                watched.rpc.events.collect { _globalEvents.tryEmit(it) }
            }
            watched.rpc.state.collect { channelState ->
                _channelState.value = channelState
                if (channelState is ChannelState.Degraded) reconnectLoop(profile)
            }
        }
    }

    /**
     * A silent socket is not the same as a healthy one. Android suspends the
     * radio; NAT tables drop idle flows; the far side can vanish without a FIN.
     * OkHttp's 20 s ping catches most of it, but a wedged server does not answer
     * RPC while still answering pings — so probe the application layer too.
     */
    private fun startHeartbeat(watched: HermesClient) {
        heartbeatJob?.cancel()
        heartbeatJob = managerScope.launch {
            while (true) {
                delay(HEARTBEAT_MS)
                if (_state.value !is ConnState.Connected) continue
                val alive = runCatching { watched.ping() }.isSuccess
                if (!alive) {
                    watched.rpc.markDegraded("heartbeat timeout")
                    return@launch
                }
            }
        }
    }

    private fun reconnectLoop(profile: ConnectionProfile) {
        if (reconnectJob?.isActive == true) return
        reconnecting = true
        reconnectJob = managerScope.launch {
            var sweeps = 0
            while (true) {
                val attempt = backoff.attempt + 1
                _state.value = ConnState.Reconnecting(currentProfile ?: profile, attempt)
                delay(backoff.nextDelay())

                val target = currentProfile ?: profile
                if (probeProfile(target)) {
                    connectLock.withLock { connectLocked(target) }
                    if (_state.value is ConnState.Connected ||
                        _state.value is ConnState.Connecting
                    ) {
                        reconnecting = false
                        return@launch
                    }
                    continue
                }

                // Address is not answering. After a few failed attempts assume
                // the lease moved rather than retrying a dead IP forever.
                if (attempt >= SWEEP_AFTER_ATTEMPTS && sweeps < MAX_SWEEPS) {
                    sweeps++
                    if (rediscoverAndRebind(target)) {
                        reconnecting = false
                        return@launch
                    }
                }
            }
        }
    }

    /**
     * A link transition is better evidence than any timer.
     *
     * The connect is deliberately NOT immediate: an Android WIFI callback lands
     * before DHCP and routing have settled, so connecting on the same tick
     * reliably lost the race. Reset the backoff (so the retry is fast, not
     * 15 s deep) and hand the work to the reconnect loop, which owns retries.
     */
    private fun onLinkChanged() {
        val profile = activeProfile ?: return
        if (!networkMonitor.onLocalNetwork) return
        if (_state.value is ConnState.Connected) return
        backoff.reset()
        reconnectLoop(profile)
    }

    /** User-visible "try now", bypassing whatever backoff is pending. */
    fun retryNow() {
        managerScope.launch {
            reconnectJob?.cancel()
            reconnecting = false
            backoff.reset()
            val profile = activeProfile
            if (profile != null) connectTo(profile) else autoConnect()
        }
    }

    private fun teardown() {
        watchJob?.cancel()
        heartbeatJob?.cancel()
        client?.rpc?.disconnect()
        activeConnection?.cookies?.clear()
        activeConnection = null
        activeStrategy = null
        client = null
        _clientFlow.value = null
    }

    fun disconnect() {
        reconnectJob?.cancel()
        reconnecting = false
        teardown()
    }

    /** Secret lookup for ancillary channels. Never log the result. */
    fun vaultSecret(profileId: String): String? = vault.secretFor(profileId)

    fun forgetProfile(id: String) {
        if (activeProfile?.id == id) {
            disconnect()
            activeProfile = null
            _state.value = ConnState.NoProfile
        }
        vault.removeProfile(id)
    }

    private companion object {
        const val HEARTBEAT_MS = 25_000L
        const val SWEEP_AFTER_ATTEMPTS = 3
        const val MAX_SWEEPS = 3
    }
}

package com.hermes.mobile.core.vault

import android.content.Context
import android.content.SharedPreferences
import androidx.security.crypto.EncryptedSharedPreferences
import androidx.security.crypto.MasterKey
import com.hermes.mobile.core.connection.ConnectionProfile
import com.hermes.mobile.core.transport.HermesJson
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.serialization.builtins.ListSerializer
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Credential vault — connection profiles and their secrets.
 *
 * Backed by EncryptedSharedPreferences (AES-256 SIV keys / AES-256 GCM values,
 * master key in Android Keystore, StrongBox when the device has one).
 * Profile metadata and secrets are both stored here: the metadata is not
 * sensitive and this keeps one obvious place to audit. Never log contents.
 */
@Singleton
class SecureVault @Inject constructor(
    @ApplicationContext context: Context,
) {
    private val prefs: SharedPreferences by lazy {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()
        EncryptedSharedPreferences.create(
            context,
            PREFS_FILE,
            masterKey,
            EncryptedSharedPreferences.PrefKeyEncryptionScheme.AES256_SIV,
            EncryptedSharedPreferences.PrefValueEncryptionScheme.AES256_GCM,
        )
    }

    private val _profiles = MutableStateFlow(loadProfiles())
    val profiles: StateFlow<List<ConnectionProfile>> = _profiles.asStateFlow()

    fun saveProfile(profile: ConnectionProfile, secret: String) {
        val updated = (_profiles.value.filterNot { it.id == profile.id } + profile)
        prefs.edit()
            .putString(KEY_PROFILES, HermesJson.encodeToString(ListSerializer(ConnectionProfile.serializer()), updated))
            .putString(secretKey(profile.id), secret)
            .apply()
        _profiles.value = updated
    }

    fun removeProfile(id: String) {
        val updated = _profiles.value.filterNot { it.id == id }
        prefs.edit()
            .putString(KEY_PROFILES, HermesJson.encodeToString(ListSerializer(ConnectionProfile.serializer()), updated))
            .remove(secretKey(id))
            .apply()
        _profiles.value = updated
    }

    fun secretFor(profileId: String): String? =
        prefs.getString(secretKey(profileId), null)?.takeIf { it.isNotBlank() }

    fun markSeen(id: String, atMs: Long = System.currentTimeMillis()) {
        val updated = _profiles.value.map { if (it.id == id) it.copy(lastSeenAt = atMs) else it }
        prefs.edit()
            .putString(KEY_PROFILES, HermesJson.encodeToString(ListSerializer(ConnectionProfile.serializer()), updated))
            .apply()
        _profiles.value = updated
    }

    private fun loadProfiles(): List<ConnectionProfile> =
        prefs.getString(KEY_PROFILES, null)?.let { raw ->
            runCatching {
                HermesJson.decodeFromString(ListSerializer(ConnectionProfile.serializer()), raw)
            }.getOrNull()
        } ?: emptyList()

    private fun secretKey(profileId: String) = "secret_$profileId"

    private companion object {
        const val PREFS_FILE = "hermes_vault"
        const val KEY_PROFILES = "connection_profiles"
    }
}

